#include "usb/ConfigProtocol.h"

#include <algorithm>
#include <array>
#include <cassert>

namespace {

using Frame = std::array<uint8_t, ConfigProtocol::FRAME_SIZE>;

// Frames generated by web/protocol.js with transaction 0x1234.
constexpr Frame request = [] {
  Frame frame = { 'H', 'S', 1, 1, 0x34, 0x12 };
  frame[60] = 0xd0;
  frame[61] = 0x6f;
  frame[62] = 0x36;
  frame[63] = 0xb3;
  return frame;
}();
constexpr Frame reply = [] {
  Frame frame = { 'H', 'S', 1, 0x81, 0x34, 0x12, 9, 0, 0, 1, 2, 7, 60, 0, 1, 0, 0 };
  frame[60] = 0x52;
  frame[61] = 0x8d;
  frame[62] = 0x7e;
  frame[63] = 0x56;
  return frame;
}();

class Handler final : public ConfigProtocol::Handler {
public:
  ConfigProtocol::Status handleConfigCommand(ConfigProtocol::Command command, std::span<const uint8_t> payload, std::span<uint8_t> response,
                                             uint8_t& responseSize) override {
    assert(command == ConfigProtocol::Command::GET_INFO);
    assert(payload.empty());
    constexpr std::array<uint8_t, 8> info = { 1, 2, 7, 60, 0, 1, 0, 0 };
    std::ranges::copy(info, response.begin());
    responseSize = info.size();
    ++calls;
    return ConfigProtocol::Status::OK;
  }

  size_t calls = 0;
};

std::span<const uint8_t> feed(ConfigProtocol& protocol, std::span<const uint8_t> bytes) {
  while (!bytes.empty() && protocol.outgoing().empty()) {
    const auto incoming = protocol.incoming();
    const size_t count = std::min(incoming.size(), bytes.size());
    std::ranges::copy(bytes.first(count), incoming.begin());
    protocol.receive(count);
    bytes = bytes.subspan(count);
  }
  return bytes;
}

void webUsbKeepsRequestAndReplyCompatible() {
  Handler handler;
  ConfigProtocol protocol(handler, ConfigProtocol::Framing::ALIGNED);
  assert(feed(protocol, request).empty());
  assert(std::ranges::equal(protocol.outgoing(), reply));
  assert(handler.calls == 1);
}

void cdcRecoversAfterNoiseAndTruncation() {
  Handler handler;
  ConfigProtocol protocol(handler, ConfigProtocol::Framing::STREAM);
  constexpr std::array<uint8_t, 63> noise{};
  assert(feed(protocol, noise).empty());
  assert(feed(protocol, std::span(request).first(1)).empty());
  assert(feed(protocol, std::span(request).subspan(1, 20)).empty());
  assert(handler.calls == 0);
  assert(feed(protocol, request).empty());
  assert(std::ranges::equal(protocol.outgoing(), reply));
  assert(handler.calls == 1);
}

void cdcProcessesCoalescedRequestsInOrder() {
  Handler handler;
  ConfigProtocol protocol(handler, ConfigProtocol::Framing::STREAM);
  std::array<uint8_t, request.size() * 2> bytes{};
  std::ranges::copy(request, bytes.begin());
  std::ranges::copy(request, bytes.begin() + request.size());
  const auto remaining = feed(protocol, bytes);
  assert(remaining.size() == request.size());
  protocol.transmit(17);
  assert(std::ranges::equal(protocol.outgoing(), std::span(reply).subspan(17)));
  protocol.transmit(protocol.outgoing().size());
  assert(feed(protocol, remaining).empty());
  assert(std::ranges::equal(protocol.outgoing(), reply));
  assert(handler.calls == 2);
}

void resettingCdcDiscardsPartialInputAndPendingOutput() {
  Handler handler;
  ConfigProtocol protocol(handler, ConfigProtocol::Framing::STREAM);
  assert(feed(protocol, std::span(request).first(30)).empty());
  protocol.reset();
  assert(protocol.incoming().size() == request.size());
  assert(feed(protocol, request).empty());
  assert(!protocol.outgoing().empty());
  protocol.reset();
  assert(protocol.outgoing().empty());
}

void invalidCrcDoesNotReachTheCommandHandler() {
  Handler handler;
  auto corrupted = request;
  corrupted[20] ^= 1;

  ConfigProtocol cdc(handler, ConfigProtocol::Framing::STREAM);
  assert(feed(cdc, corrupted).empty());
  assert(cdc.outgoing().empty());

  ConfigProtocol webUsb(handler, ConfigProtocol::Framing::ALIGNED);
  assert(feed(webUsb, corrupted).empty());
  const auto error = webUsb.outgoing();
  assert(error.size() == ConfigProtocol::FRAME_SIZE);
  assert(error[8] == static_cast<uint8_t>(ConfigProtocol::Status::BAD_FRAME));
  assert(handler.calls == 0);
}

} // namespace

int main() {
  webUsbKeepsRequestAndReplyCompatible();
  cdcRecoversAfterNoiseAndTruncation();
  cdcProcessesCoalescedRequestsInOrder();
  resettingCdcDiscardsPartialInputAndPendingOutput();
  invalidCrcDoesNotReachTheCommandHandler();
}
